// Generated by Claude (Opus 5.5), 2026-10-25
// itch-replay.cpp
// Replay a NASDAQ TotalView-ITCH 5.0 file over UDP as MoldUDP64 packets, for ItchParser.
//
// Input is a decompressed NASDAQ day file (e.g. 01302019.NASDAQ_ITCH50): each message is
// a 2-byte big-endian length followed by the message. Sequence numbers are the message's
// position in the file (1-based), so the receiver's gap detection sees real numbers.
//
// A window of --messages messages, starting at the first message stamped at or after
// --from, is packed into packets before anything is sent: the send loop only paces and
// calls sendmmsg. The last packet is end-of-session, so ItchParser::start() returns.
//
// Build: g++-14 -std=c++23 -O2 -march=native itch-replay.cpp -o ../../../build/itch-replay
// Run:   itch-replay --file ~/itch-data/01302019.NASDAQ_ITCH50 --speed 10
//
// --speed X  replays the ITCH timestamps X times faster than real time (bursts kept).
// --speed 0  sends as fast as sendmmsg goes; the receiver will drop packets if it lags.
//
// Last line printed (spsc-bench.sh compares it with the receiver's):
//   summary: messages=N ticks=T qty=Q
// ticks and qty count the messages ItchParser turns into Ticks (E, printable C, P, Q).

#include <arpa/inet.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/stat.h>
#include <unistd.h>

#include <algorithm>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <string_view>
#include <thread>
#include <vector>

namespace {

struct Options {
    std::string file;
    std::string host = "127.0.0.1";       // destination, unicast or a multicast group
    std::string interface_ip;             // multicast only: outgoing interface
    std::uint16_t port = 12345;
    std::uint64_t from_ns = 34'200ull * 1'000'000'000;   // 09:30:00
    std::uint64_t messages = 20'000'000;
    double speed = 10.0;
    std::size_t packet_bytes = 1400;      // stays under a 1500-byte MTU
    unsigned batch = 32;                  // packets per sendmmsg at most
};

constexpr char session[10] = {'I', 'T', 'C', 'H', 'R', 'E', 'P', 'L', 'A', 'Y'};
constexpr std::size_t mold_header_size = 20;
constexpr std::uint64_t mold_end_of_session = 0xFFFF;

template <std::size_t nbytes>
std::uint64_t load_be(const std::uint8_t* p) {
    std::uint64_t value = 0;
    for (std::size_t i = 0; i < nbytes; i++) value = (value << 8) | p[i];
    return value;
}

template <std::size_t nbytes>
void store_be(std::uint8_t* p, std::uint64_t value) {
    for (std::size_t i = 0; i < nbytes; i++) p[i] = static_cast<std::uint8_t>(value >> (8 * (nbytes - 1 - i)));
}

[[noreturn]] void die(const char* what) {
    std::perror(what);
    std::exit(1);
}

[[noreturn]] void usage(const char* argv0) {
    std::fprintf(stderr,
                 "usage: %s --file PATH [--from HH:MM:SS] [--messages N] [--speed X]\n"
                 "          [--host IP] [--port N] [--interface IP] [--packet-bytes N] [--batch N]\n",
                 argv0);
    std::exit(2);
}

std::uint64_t parse_time_of_day(const char* s) {
    unsigned h = 0, m = 0, sec = 0;
    if (std::sscanf(s, "%u:%u:%u", &h, &m, &sec) < 2) {
        std::fprintf(stderr, "bad --from %s, expected HH:MM[:SS]\n", s);
        std::exit(2);
    }
    return ((h * 60ull + m) * 60ull + sec) * 1'000'000'000ull;
}

Options parse_args(int argc, char** argv) {
    Options o;
    for (int i = 1; i < argc; i++) {
        const std::string_view a = argv[i];
        if (i + 1 >= argc) usage(argv[0]);
        const char* v = argv[++i];
        if (a == "--file") o.file = v;
        else if (a == "--host") o.host = v;
        else if (a == "--interface") o.interface_ip = v;
        else if (a == "--port") o.port = static_cast<std::uint16_t>(std::atoi(v));
        else if (a == "--from") o.from_ns = parse_time_of_day(v);
        else if (a == "--messages") o.messages = std::strtoull(v, nullptr, 10);
        else if (a == "--speed") o.speed = std::atof(v);
        else if (a == "--packet-bytes") o.packet_bytes = std::strtoull(v, nullptr, 10);
        else if (a == "--batch") o.batch = static_cast<unsigned>(std::atoi(v));
        else usage(argv[0]);
    }
    if (o.file.empty() || o.batch == 0 || o.packet_bytes < mold_header_size + 2 + 64) usage(argv[0]);
    return o;
}

// The packets, back to back in one buffer.
struct Packet {
    std::size_t offset;
    std::size_t len;
    std::uint64_t ts_ns;   // ITCH timestamp of its first message
};

struct Window {
    std::vector<std::uint8_t> bytes;
    std::vector<Packet> packets;
    std::uint64_t first_sequence = 0;
    std::uint64_t next_sequence = 0;     // after the last message sent
    std::uint64_t messages = 0;
    std::uint64_t ticks = 0;
    std::uint64_t qty = 0;
};

// Same rules as ItchParser::on_message: which messages become Ticks, and their shares.
void count_tick(const std::uint8_t* msg, std::size_t len, Window& w) {
    switch (msg[0]) {
        case 'E': if (len >= 31) { ++w.ticks; w.qty += load_be<4>(msg + 19); } break;
        case 'C': if (len >= 36 && msg[31] != 'N') { ++w.ticks; w.qty += load_be<4>(msg + 19); } break;
        case 'P': if (len >= 44) { ++w.ticks; w.qty += load_be<4>(msg + 20); } break;
        case 'Q': if (len >= 40) { ++w.ticks; w.qty += load_be<8>(msg + 11); } break;
        default: break;
    }
}

Window build_window(const std::uint8_t* data, std::size_t size, const Options& o) {
    Window w;
    std::size_t off = 0;
    std::uint64_t sequence = 1;

    // Skip to --from. A message too short for a timestamp cannot be the start.
    while (off + 2 <= size) {
        const std::size_t len = load_be<2>(data + off);
        if (off + 2 + len > size) break;
        if (len >= 11 && load_be<6>(data + off + 2 + 5) >= o.from_ns) break;
        off += 2 + len;
        ++sequence;
    }

    w.first_sequence = sequence;
    w.bytes.reserve(std::min<std::size_t>(size - off, o.messages * 48) + o.messages / 20 * mold_header_size);

    std::size_t packet_start = 0;
    std::uint64_t packet_count = 0;

    auto close_packet = [&] {
        if (packet_count == 0) return;
        store_be<2>(w.bytes.data() + packet_start + 18, packet_count);
        w.packets.back().len = w.bytes.size() - packet_start;
        packet_count = 0;
    };

    while (w.messages < o.messages && off + 2 <= size) {
        const std::size_t len = load_be<2>(data + off);
        if (off + 2 + len > size) break;          // truncated last message
        const std::uint8_t* msg = data + off + 2;

        if (packet_count != 0 && w.bytes.size() - packet_start + 2 + len > o.packet_bytes) close_packet();

        if (packet_count == 0) {
            packet_start = w.bytes.size();
            w.bytes.resize(packet_start + mold_header_size);
            std::memcpy(w.bytes.data() + packet_start, session, sizeof session);
            store_be<8>(w.bytes.data() + packet_start + 10, sequence);
            w.packets.push_back({packet_start, 0, len >= 11 ? load_be<6>(msg + 5) : 0});
        }

        // Length prefix and message are already laid out as MoldUDP64 wants them
        w.bytes.insert(w.bytes.end(), data + off, data + off + 2 + len);
        ++packet_count;
        ++w.messages;
        ++sequence;
        if (len >= 11) count_tick(msg, len, w);
        off += 2 + len;
    }
    close_packet();
    w.next_sequence = sequence;
    return w;
}

int open_socket(const Options& o, sockaddr_in& dest) {
    const int fd = ::socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) die("socket");

    const int sndbuf = 16 << 20;
    ::setsockopt(fd, SOL_SOCKET, SO_SNDBUF, &sndbuf, sizeof sndbuf);   // best effort

    dest = {};
    dest.sin_family = AF_INET;
    dest.sin_port = htons(o.port);
    if (::inet_pton(AF_INET, o.host.c_str(), &dest.sin_addr) != 1) {
        std::fprintf(stderr, "bad --host %s\n", o.host.c_str());
        std::exit(2);
    }

    if (IN_MULTICAST(ntohl(dest.sin_addr.s_addr))) {
        const unsigned char loop = 1;
        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_LOOP, &loop, sizeof loop) != 0) die("IP_MULTICAST_LOOP");
        if (!o.interface_ip.empty()) {
            in_addr itf{};
            if (::inet_pton(AF_INET, o.interface_ip.c_str(), &itf) != 1) {
                std::fprintf(stderr, "bad --interface %s\n", o.interface_ip.c_str());
                std::exit(2);
            }
            if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_IF, &itf, sizeof itf) != 0) die("IP_MULTICAST_IF");
        }
    }
    return fd;
}

}  // namespace

int main(int argc, char** argv) {
    const Options o = parse_args(argc, argv);

    const int file_fd = ::open(o.file.c_str(), O_RDONLY);
    if (file_fd < 0) die(o.file.c_str());
    struct stat st{};
    if (::fstat(file_fd, &st) != 0) die("fstat");
    const std::size_t size = static_cast<std::size_t>(st.st_size);
    void* map = ::mmap(nullptr, size, PROT_READ, MAP_PRIVATE, file_fd, 0);
    if (map == MAP_FAILED) die("mmap");
    ::madvise(map, size, MADV_SEQUENTIAL);

    const Window w = build_window(static_cast<const std::uint8_t*>(map), size, o);
    ::munmap(map, size);
    ::close(file_fd);

    if (w.packets.empty()) {
        std::fprintf(stderr, "no messages at or after --from in %s\n", o.file.c_str());
        return 1;
    }
    const double span_s = static_cast<double>(w.packets.back().ts_ns - w.packets.front().ts_ns) / 1e9;
    std::printf("window: sequence %llu, %llu messages in %zu packets, %llu ticks, %.1f s of market time\n",
                static_cast<unsigned long long>(w.first_sequence), static_cast<unsigned long long>(w.messages),
                w.packets.size(), static_cast<unsigned long long>(w.ticks), span_s);
    std::fflush(stdout);

    sockaddr_in dest{};
    const int fd = open_socket(o, dest);

    std::vector<iovec> iov(o.batch);
    std::vector<mmsghdr> msgs(o.batch);
    std::uint64_t send_errors = 0;

    using clock = std::chrono::steady_clock;
    const auto wall_start = clock::now();
    const std::uint64_t ts_start = w.packets.front().ts_ns;

    std::size_t next = 0;
    while (next < w.packets.size()) {
        std::size_t end = next;
        if (o.speed > 0) {
            // Busy-wait for the first packet that is due, then send every packet due by now.
            const auto due = [&](std::size_t i) {
                return wall_start + std::chrono::nanoseconds(static_cast<std::int64_t>(
                                        static_cast<double>(w.packets[i].ts_ns - ts_start) / o.speed));
            };
            while (clock::now() < due(next)) {}
            const auto now = clock::now();
            end = next + 1;
            while (end < w.packets.size() && end - next < o.batch && due(end) <= now) ++end;
        } else {
            end = std::min(w.packets.size(), next + o.batch);
        }

        const unsigned n = static_cast<unsigned>(end - next);
        for (unsigned i = 0; i < n; i++) {
            const Packet& p = w.packets[next + i];
            iov[i] = {const_cast<std::uint8_t*>(w.bytes.data() + p.offset), p.len};
            msgs[i] = {};
            msgs[i].msg_hdr.msg_name = const_cast<sockaddr_in*>(&dest);
            msgs[i].msg_hdr.msg_namelen = sizeof dest;
            msgs[i].msg_hdr.msg_iov = &iov[i];
            msgs[i].msg_hdr.msg_iovlen = 1;
        }
        unsigned sent = 0;
        while (sent < n) {
            const int r = ::sendmmsg(fd, msgs.data() + sent, n - sent, 0);
            if (r < 0) {
                if (errno == EINTR || errno == EAGAIN || errno == ENOBUFS) continue;
                // ECONNREFUSED and the like: the packet is gone, carry on (the receiver counts the gap)
                ++send_errors;
                ++sent;
                continue;
            }
            sent += static_cast<unsigned>(r);
        }
        next = end;
    }
    const double send_s = std::chrono::duration<double>(clock::now() - wall_start).count();

    // Give the receiver time to drain its socket buffer, then end the session. Sent a few
    // times because a UDP packet can be dropped; the receiver stops at the first one.
    std::this_thread::sleep_for(std::chrono::milliseconds(200));
    std::uint8_t eos[mold_header_size];
    std::memcpy(eos, session, sizeof session);
    store_be<8>(eos + 10, w.next_sequence);
    store_be<2>(eos + 18, mold_end_of_session);
    for (int i = 0; i < 3; i++) {
        ::sendto(fd, eos, sizeof eos, 0, reinterpret_cast<const sockaddr*>(&dest), sizeof dest);
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }
    ::close(fd);

    std::printf("sent in %.3f s: %.2f M msg/s, %.2f M ticks/s, %.0f k packets/s, %llu send errors\n", send_s,
                static_cast<double>(w.messages) / send_s / 1e6, static_cast<double>(w.ticks) / send_s / 1e6,
                static_cast<double>(w.packets.size()) / send_s / 1e3,
                static_cast<unsigned long long>(send_errors));
    std::printf("summary: messages=%llu ticks=%llu qty=%llu\n", static_cast<unsigned long long>(w.messages),
                static_cast<unsigned long long>(w.ticks), static_cast<unsigned long long>(w.qty));
    return 0;
}
